# initialize_parameters ----
## Setup ----
# `small_parameters` is in helper-small-parameters.R.

## IO correctness ----
test_that("`initialize_parameters()` works with correct inputs", {
  parameters <- small_parameters |>
    add_priors(
      log_q ~ normal(mean = log(0.5), sd = 0.2),
      module_name = "Fleet",
      fleet = "survey1"
    )
  parameter_table <- FIMS:::initialize_parameters(
    parameters
  )[["parameter_table"]]
  #' @description Test that `initialize_parameters()` names prior rows apart from a process's own parameters.
  expect_setequal(
    object = parameter_table[["name"]][
      parameter_table[["distribution_type"]] %in% "prior"
    ],
    expected = c(
      "Fleet.survey1.log_q_prior_expected_mean",
      "Fleet.survey1.log_q_prior_log_sd"
    )
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`initialize_parameters()` returns correct error messages", {
  shared_parameters <- small_parameters |>
    dplyr::mutate(
      value = dplyr::if_else(label == "log_Fmort", -(1:7) / 2, value),
      map_group = dplyr::if_else(label == "log_Fmort", 1L, NA_integer_)
    )
  #' @description Test that `initialize_parameters()` errors when rows that share 1 estimate start from different values.
  expect_error(
    object = FIMS:::initialize_parameters(shared_parameters),
    regexp = "identical starting"
  )
  unsorted_parameters <- small_parameters |>
    dplyr::mutate(
      value = dplyr::if_else(label == "log_Fmort", -timing / 10, value)
    ) |>
    dplyr::arrange(dplyr::desc(timing))
  withr::local_options(rlib_message_verbosity = "default")
  #' @description Test that `initialize_parameters()` gives a message for rows out of year order.
  expect_message(
    object = sorted <- FIMS:::initialize_parameters(unsorted_parameters),
    regexp = "not in year and age order"
  )
  #' @description Test that `initialize_parameters()` matches each value to its own year when the rows are out of order.
  expect_equal(
    object = as.vector(sorted[["parameters"]][["Fleet.fleet1.log_Fmort"]]),
    expected = -(1:6) / 10
  )
  #' @description Test that `initialize_parameters()` errors for a second row of a parameter with 1 value, which would otherwise be recycled.
  expect_error(
    object = FIMS:::initialize_parameters(
      dplyr::bind_rows(small_parameters, dplyr::slice(small_parameters, 1))
    ),
    regexp = "more than 1 row with\\s+the\\s+same"
  )
  #' @description Test that `initialize_parameters()` errors for 2 rows of a parameter in the same year.
  expect_error(
    object = FIMS:::initialize_parameters(
      dplyr::mutate(small_parameters, timing = dplyr::if_else(
        timing %in% 2, 1, timing
      ))
    ),
    regexp = "more than 1 row with\\s+the\\s+same"
  )
})

