## IO correctness ----
test_that("`map_levels()` works with correct inputs", {
  #' @description Test that `map_levels()` gives fixed values NA, rows with the same map_group 1 shared level, and every other estimated value its own level.
  expect_equal(
    object = FIMS:::map_levels(
      c(TRUE, TRUE, FALSE, TRUE, TRUE),
      c(1, 1, NA, NA, 2)
    ),
    expected = c(1L, 1L, NA, 2L, 3L)
  )
})

